commands.buildNextAptActions:
buildNextAptActions = (g: typeof goLog[number]) => {
    const isAquiSending = aquiSendingId === g.id;
    return [
      {
        k: "here",
        label: isAquiSending ? "GPS…" : t('here'),
        icon: "map-pin" as const,
        color: "#60a5fa",
        fn: async () => {
          if (isAquiSending) return;
          setAquiSendingId(g.id);
          let coords: { lat: number; lng: number } | null = null;
          try {
            const perms = await Location.getForegroundPermissionsAsync();
            let status = perms.status;
            if (status !== "granted" && perms.canAskAgain) {
              const req = await Location.requestForegroundPermissionsAsync();
              status = req.status;
            }
            if (status === "granted") {
              try {
                const last = await Location.getLastKnownPositionAsync({
                  maxAge: 1000 * 60 * 5,
                });
                if (last?.coords) {
                  coords = {
                    lat: last.coords.latitude,
                    lng: last.coords.longitude,
                  };
                }
              } catch {}
              if (!coords) {
                try {
                  const pos = await Location.getCurrentPositionAsync({
                    accuracy: Location.Accuracy.Balanced,
                  });
                  coords = {
                    lat: pos.coords.latitude,
                    lng: pos.coords.longitude,
                  };
                } catch {}
              }
            }
          } catch {}
          const dest = normalizePhoneForWhatsApp(g.phone);
          let txt: string;
          const safeLabel = (g.intentLabel ?? "GO").toUpperCase();
          if (coords) {
            const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${coords.lat},${coords.lng}`;
            txt =
              `📍 Estoy aquí · ${safeLabel}\n${mapsUrl}` +
              (g.place ? `\n(Cita: ${g.place})` : "");
          } else {
            txt =
              `📍 Estoy aquí · ${safeLabel}` +
              (g.place ? ` (${g.place})` : "");
          }
          try {
            const url = dest
              ? `https://wa.me/${dest}?text=${encodeURIComponent(txt)}`
              : `https://wa.me/?text=${encodeURIComponent(txt)}`;
            await Linking.openURL(url);
            showToast(coords ? t('toast_location_sent') : t('toast_alert_no_gps'));
          } catch {
            showToast(t('toast_location_fail'), 'error');
          } finally {
            setAquiSendingId(null);
          }
        },
      },
      {
        k: "late",
        label: t('late'),
        icon: "alert-circle" as const,
        color: "#fde68a",
        fn: () => {
          setLateSheetGo(g);
        },
      },
      {
        k: "snooze",
        label: "+10m",
        icon: "clock" as const,
        color: "#fbbf24",
        fn: () => {
          snoozeGoReminder(g.id, 10);
        },
      },
      {
        k: "change",
        label: t('change'),
        icon: "edit-3" as const,
        color: "#fb923c",
        fn: () => {
          currentReceivedIdRef.current = g.id;
          proposalReturnRef.current = "landing";
          Haptics.selectionAsync();
          setCalOpen(true);
          calFlow.open({
            startAt: "date",
            initialDateISO: g.dateISO || formatISODate(getToday()),
            initialDateDraft: g.date || "",
            initialTime: g.time || "",
            initialDuration: g.duration || "",
            onSave: (r: CalFlowResult) => { sendSuggestChangeFromCal(r); },
            onCancel: () => { setCalOpen(false); },
          });
        },
      },
    ];
  }

commands.nextCardPanRef:
nextCardPanRef = useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: (_e, g) => {
        const absX = Math.abs(g.dx);
        const absY = Math.abs(g.dy);
        return nextCardTotalRef.current > 1 && absX > 8 && absX > absY * 1.4;
      },
      onMoveShouldSetPanResponderCapture: (_e, g) => {
        const absX = Math.abs(g.dx);
        const absY = Math.abs(g.dy);
        return nextCardTotalRef.current > 1 && absX > 8 && absX > absY * 1.4;
      },
      onPanResponderGrant: () => {
        // Stop any running animation and reset to 0 so the card never drifts
        // from a non-zero intermediate value between gestures.
        nextCardSlideAnim.stopAnimation();
        nextCardSlideAnim.setValue(0);
      },
      onPanResponderRelease: (_e, g) => {
        const safeIdx = Math.min(nextCardIdxRef.current, nextCardTotalRef.current - 1);
        const total = nextCardTotalRef.current;
        if (g.dx < -20 && safeIdx < total - 1) {
          Animated.sequence([
            Animated.timing(nextCardSlideAnim, { toValue: -18, duration: 90, useNativeDriver: true }),
            Animated.timing(nextCardSlideAnim, { toValue: 0, duration: 130, useNativeDriver: true }),
          ]).start(() => nextCardSlideAnim.setValue(0));
          nextCardSetIdxRef.current(safeIdx + 1);
          Haptics.selectionAsync().catch(() => {});
        } else if (g.dx > 20 && safeIdx > 0) {
          Animated.sequence([
            Animated.timing(nextCardSlideAnim, { toValue: 18, duration: 90, useNativeDriver: true }),
            Animated.timing(nextCardSlideAnim, { toValue: 0, duration: 130, useNativeDriver: true }),
          ]).start(() => nextCardSlideAnim.setValue(0));
          nextCardSetIdxRef.current(safeIdx - 1);
          Haptics.selectionAsync().catch(() => {});
        } else {
          // Swipe too short or at boundary — ensure value is clean.
          nextCardSlideAnim.setValue(0);
        }
      },
      // Handle system-level gesture termination (notifications, edge swipes,
      // native ScrollViews stealing the responder). Without this, the
      // Animated.Value can be left at a non-zero intermediate position and
      // the gesture system enters a frozen state for all subsequent touches.
      onPanResponderTerminate: () => {
        nextCardSlideAnim.stopAnimation();
        nextCardSlideAnim.setValue(0);
      },
      onPanResponderTerminationRequest: () => false,
    }),
  ).current

commands.cambiosCardPanRef:
cambiosCardPanRef = useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: (_e, g) => {
        return cambiosCardTotalRef.current > 1 && Math.abs(g.dx) > 8 && Math.abs(g.dx) > Math.abs(g.dy) * 1.4;
      },
      onMoveShouldSetPanResponderCapture: (_e, g) => {
        return cambiosCardTotalRef.current > 1 && Math.abs(g.dx) > 8 && Math.abs(g.dx) > Math.abs(g.dy) * 1.4;
      },
      onPanResponderRelease: (_e, g) => {
        const total = cambiosCardTotalRef.current;
        const safeIdx = Math.min(cambiosCardIdxRef.current, total - 1);
        const nextIdx = g.dx < -24 && safeIdx < total - 1 ? safeIdx + 1
          : g.dx > 24 && safeIdx > 0 ? safeIdx - 1 : safeIdx;
        if (nextIdx !== safeIdx) {
          LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
          setCambiosCardIdx(nextIdx);
          Haptics.selectionAsync().catch(() => {});
        }
      },
      onPanResponderTerminationRequest: () => false,
    }),
  ).current

commands.wrapOrbital:
wrapOrbital = (inner: React.ReactNode) => {
    // V1 PROMPT 13 — SISTEMA DE CAPAS.
    // Cualquier capa no-IA abierta (listado, calendario, contactos,
    // mapa, modo, sheets de respuesta/sugerencia/cancelación, "Llego
    // tarde", resumen IA…) ESCONDE GO por completo. Devolvemos null:
    // el wrapper exterior es absolute, así que no deja hueco. Cuando
    // la capa se cierre, `anyOverlayOpen` pasa a false y este helper
    // vuelve a renderizar el bloque absoluto draggable con GO en su
    // posición persistida (zona pulgar) — el efecto de animación
    // resetea overlayDX/overlayDY/aiShrink en paralelo.
    //
    // EXCEPCIÓN: Listado Global con espacio suficiente → GO de fondo.
    // No interactivo, centrado en el hueco superior, detrás del panel.
    if (anyOverlayOpen && !aiOpen) {
      // Listado: solo si hay espacio visual (lista muy larga → sin hueco)
      if (listOpen && !listGoVisible) return null;
      // OrbitalDockWrapper — overlay ghost (non-interactive, faded)
      return (
        <View
          pointerEvents="none"
          style={{
            position: "absolute",
            bottom: insets.bottom + SYSTEM_MARGIN_Y,
            right: dockRight,
            width: systemBoundingRadius * 2,
            height: systemBoundingRadius * 2,
          }}
        >
          <Animated.View
            pointerEvents="none"
            style={{
              position: "absolute",
              left: systemBoundingRadius - orbitWrapSize / 2,
              top: systemBoundingRadius * 2 - orbitWrapSize,
              width: orbitWrapSize,
              height: orbitWrapSize,
              zIndex: 4,
              opacity: posReady ? 0.82 : 0,
              shadowColor: "#6ee7b7",
              shadowOpacity: 0.22,
              shadowRadius: 32,
              shadowOffset: { width: 0, height: 0 },
              transform: [
                { translateX: pan.x },
                { translateY: pan.y },
                { translateX: overlayDX },
                { translateY: overlayDY },
                { scale: aiShrink },
              ],
            }}
          >
            {inner}
          </Animated.View>
        </View>
      );
    }
    if (aiOpen) {
      return (
        <View
          pointerEvents="box-none"
          onLayout={(e) => {
            const { width, height } = e.nativeEvent.layout;
            setIaContainerLayout((prev) => {
              if (
                prev &&
                Math.abs(prev.width - width) < 0.5 &&
                Math.abs(prev.height - height) < 0.5
              ) {
                return prev;
              }
              return { width, height };
            });
          }}
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: titleBottomLocalY ?? 0,
            bottom: kbHeight + overlayPanelHeight,
            alignItems: "center",
            justifyContent: "center",
            zIndex: 20,
          }}
        >
          <Animated.View
            pointerEvents="box-none"
            style={{
              width: orbitWrapSize,
              height: orbitWrapSize,
              opacity:
                posReady && titleBottomLocalY !== null && iaContainerLayout
                  ? 1
                  : 0,
            }}
          >
            {inner}
          </Animated.View>
        </View>
      );
    }
    // ── OrbitalDockWrapper (draggable) ──────────────────────────────────
    // Outer View: static absolute layer anchored bottom-right.
    //   bottom: insets.bottom + SYSTEM_MARGIN_Y
    //   right:  SYSTEM_MARGIN_X
    //   size:   systemBoundingRadius * 2 (full bounding box)
    // Inner Animated.View: centered within the dock, translated by pan.
    //   pan = (0,0) → orbital center at dock center = bottom-right anchor.
    //   pan.x < 0 → moved left; pan.y < 0 → moved up.
    // Overflow remains visible. The Landing position is anchored and cannot
    // be moved by touch; `pan` is reserved for existing safe-layout anchors.
    return (
      <View
        pointerEvents="box-none"
        style={{
          position: "absolute",
          bottom: insets.bottom + SYSTEM_MARGIN_Y,
          right: dockRight,
          width: systemBoundingRadius * 2,
          height: systemBoundingRadius * 2,
        }}
      >
        <Animated.View
          style={{
            position: "absolute",
            left: systemBoundingRadius - orbitWrapSize / 2,
            top: systemBoundingRadius * 2 - orbitWrapSize,
            width: orbitWrapSize,
            height: orbitWrapSize,
            opacity: posReady ? 1 : 0,
            transform: [
              { translateX: pan.x },
              { translateY: pan.y },
              { translateY: kbOrbitTranslate },
              { translateX: overlayDX },
              { translateY: overlayDY },
            ],
          }}
        >
          {inner}
        </Animated.View>
      </View>
    );
  }

