surgical.closeTopLayer:
closeTopLayer = () => {
    // ── -1. CHECKOUT MARKETPLACE — retrocede a orbit normal ───────────────
    if (marketplaceCheckout !== null) {
      setMarketplaceCheckout(null);
      setCheckoutDone(new Set());
      return;
    }
    // ── 0. MODO RUTAS ─────────────────────────────────────────────────────
    if (rutasMode)                 { setRutasMode(false);            return; }
    // ── 1. COMPRAS — capa más profunda ───────────────────────────────────
    if (pedidoTrackingOpen)        { setPedidoTrackingOpen(false);   return; }
    if (empresaOpen)               { setEmpresaOpen(false);          return; }
    // ── 2. SATÉLITES SECUNDARIOS ──────────────────────────────────────────
    if (activeSatCtx !== null)     { setActiveSatCtx(null);          return; }
    if (orbitSecondLevel !== null) {
      if (orbitSubIntentKey !== null) {
        orbitsAnim.setValue(0);
        Animated.spring(orbitsAnim, { toValue: 1, useNativeDriver: true, speed: 20, bounciness: 7 }).start();
        setOrbitSubIntentKey(null);
      }
      else if (orbitSecondLayerIndex > 0) { setOrbitSecondLayerIndex(i => i - 1); }
      else { setOrbitSecondLevel(null); }
      return;
    }
    // ── 3. SUB-OVERLAYS Y SELECTORES ─────────────────────────────────────
    if (remindClockOpen)           { setRemindClockOpen(false);      return; }
    if (goSearchOpen)              { setGoSearchOpen(false); setGoSearchSub(null); setGoSearchQuery(""); return; }
    if (reservasOrbitalOpen) {
      if (reservasOrbitalCat !== null) {
        if (reservasOrbitalPage > 0) { setReservasOrbitalPage(p => p - 1); }
        else { setReservasOrbitalCat(null); setReservasOrbitalPage(0); }
      } else { setReservasOrbitalOpen(false); }
      return;
    }
    if (otrosOpen)                 { setOtrosOpen(false);            return; }
    if (fieldSelectorOpen)         { setFieldSelectorOpen(false);    return; }
    if (sugerirOpen)               { setSugerirOpen(false);          return; }
    // ── 4. OVERLAYS DE DETALLE ────────────────────────────────────────────
    if (aiSummaryOpen)             { setAiSummaryOpen(false);        return; }
    if (respondOpen)               { setRespondOpen(false);          return; }
    if (suggestOpen)               { setSuggestOpen(false);          return; }
    if (cancelOpen)                { setCancelOpen(false);           return; }
    if (silencedOpen)              { setSilencedOpen(false);         return; }
    if (qrOpen)                    { setQrOpen(false);               return; }
    if (blockedOpen)               { setBlockedOpen(false);          return; }
    if (receivedDetailOpen)        { setReceivedDetailOpen(false);   return; }
    if (lateSheetGo)               { setLateSheetGo(null);           return; }
    // ── 5. OVERLAYS PRINCIPALES ───────────────────────────────────────────
    if (aiOpen)                    { setAiOpen(false);               return; }
    if (calReservasOpen)           { setCalReservasOpen(false);      return; }
    if (agendaOpOpen)              { setAgendaOpOpen(false);         return; }
    if (calOpen)                   { setCalOpen(false);              return; }
    if (listOpen)                  { setListOpen(false);             return; }
    if (contactOpen)               { setContactOpen(false);          return; }
    if (mapOpen)                   { setMapOpen(false);              return; }
    if (messagesOpen)              { setMessagesOpen(false);         return; }
    if (humanityOpen)              { setHumanityOpen(false);         return; }
    if (modeOpen)                  { setModeOpen(false);             return; }
    if (cuentaOpen)                { setCuentaOpen(false);           return; }
    if (optionsOpen)               { setOptionsOpen(false);          return; }
    if (notesOpen)                 { setNotesOpen(false);            return; }
    if (proposalListOpen)          { setProposalListOpen(false);     return; }
    // ── 6. PRÓXIMA VISITA Y/O CAMBIOS ABIERTOS ──────────────────────────
    if (!nextAptMinimized || cambiosOpen) {
      if (!nextAptMinimized) setNextAptMinimized(true);
      if (cambiosOpen) setCambiosOpen(false);
      return;
    }
    // ── 7. SELECCIÓN ACTIVA DEL GO — campos rellenos O categoría elegida ──
    // Cubre: tap en "Comida"/"Reunión" sin campos (categorySelected solo),
    // campos parcialmente rellenos, o ambos juntos. Un toque → todo limpio.
    if (isActivelyCreating || categorySelected || otroSelected) {
      resetContactFields();
      setCategorySelected(false);
      setOtroSelected(false);
      setGenericMode(false);
      setSelectedSugerencia(null);
      return;
    }
    // ── 8. SAFETY NET — landing ya limpio ────────────────────────────────
    closeAllOverlays();
  }

surgical.universalSwipeGesture:
universalSwipeGesture = useMemo(
    () =>
      Gesture.Pan()
        .enabled(!goAuthOpen)
        .runOnJS(true)
        .activeOffsetY(40)
        .failOffsetX([-65, 65])
        .onStart((e) => {
          const w = Dimensions.get("window").width;
          const h = Dimensions.get("window").height;
          swipeStartZoneRef.current.valid =
            e.absoluteY > h * 0.45 && e.absoluteX > w * 0.32;
        })
        .onEnd((e) => {
          if (!swipeStartZoneRef.current.valid) return;
          if (e.translationY < 80) return;
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
          swipeHandlersRef.current.closeAllOverlays();
          swipeHandlersRef.current.resetContactFields();
          swipeHandlersRef.current.setOtrosOpen(false);
        }),
    [goAuthOpen],
  )

